function projection(rows, sourceFor, helper) {
 const results=[],fail=[];let functionCount=0,orderCount=0,rawCount=0,forbiddenCount=0,topCount=0,literalCount=0;
 const esc=s=>s.replace(/[.*+?^\${}()|[\]\\]/g,"\\$&");
 const occurrence=(s,m)=>{const out=[];let k=0;while(true){let at=s.indexOf(m,k);if(at<0)break;out.push(at);k=at+m.length;}return out;};
 for(let rowIndex=0;rowIndex<rows.length;rowIndex++){
  const row=rows[rowIndex];if(row.kind!=="protected_file")continue;
  const source=sourceFor(row.key);if(typeof source!=="string")continue;
  const d=row.data,code=helper.stripCfgTest(helper.stripNonCode(source));
  const rr={table_row:rowIndex,path:row.key,raw:[],file_order:[],functions:[],forbidden:[]};
  for(const marker of d.required||[]){rawCount++;const at=source.indexOf(marker);rr.raw.push({marker,start:at});if(at<0)fail.push({path:row.key,row:rowIndex,kind:"required",marker});}
  for(const seq of d.required_order||[]){const check=helper.ordered(code,seq);orderCount+=seq.length;rr.file_order.push(check);if(!check.ok)fail.push({path:row.key,row:rowIndex,kind:"file_order",check});}
  for(const f of d.required_function_order||[]){
   functionCount++;const ff={function:f.function,top_level:[],literal_calls:[]};
   try{
    if(!/^fn [A-Za-z_]\w*\($/.test(f.function))throw Error("invalid function marker");
    const part=helper.functionBody(source,f.function);ff.extent={start:part.start,end:part.end,nestedCount:part.nestedCount};
    for(const marker of f.top_level||[]){
     topCount++;const at=occurrence(part.body,marker);let depth=null;
     if(at.length===1){const prefix=part.body.slice(0,at[0]);depth=(prefix.match(/{/g)||[]).length-(prefix.match(/}/g)||[]).length;}
     ff.top_level.push({marker,matches:at,depth});
     if(at.length!==1||depth!==1)fail.push({path:row.key,row:rowIndex,kind:"top_level",function:f.function,marker,matches:at,depth});
    }
    const lit={};const ms=f.literal_calls||[];if(new Set(ms).size!==ms.length)throw Error("duplicate literal_calls");
    for(const marker of ms){
     literalCount++;const masked=helper.stripNonCode(marker);
     if(!/^(?:\.[A-Za-z_]\w*|[A-Za-z_]\w*(?:::[A-Za-z_]\w*)*)\("(?:[^"\\]|\\.)*"\)$/.test(marker)||!masked.trim()||masked===marker)throw Error("invalid literal call");
     const positions=occurrence(source.slice(part.start,part.end+1),marker).filter(at=>part.body.slice(at,at+marker.length)===masked);
     ff.literal_calls.push({marker,matches:positions});if(positions.length!==1)throw Error("literal call does not have one actual code match");lit[marker]=positions[0];
    }
    if(!Array.isArray(f.sequence)||f.sequence.length<2||f.sequence.some(m=>typeof m!=="string"||!m))throw Error("invalid function order");
    let offset=0;const matches=[];for(const marker of f.sequence){const at=marker in lit?lit[marker]:part.body.indexOf(marker,offset);if(at<offset)throw Error("required marker missing after "+offset+": "+JSON.stringify(marker));matches.push({marker,start:at,end:at+marker.length});offset=at+marker.length;}
    orderCount+=f.sequence.length;ff.order={ok:true,matches};
   }catch(e){ff.error=String(e);fail.push({path:row.key,row:rowIndex,kind:"function_order",function:f.function,error:String(e)});}
   rr.functions.push(ff);
  }
  for(const marker of d.forbidden||[]){
   forbiddenCount++;let pat=esc(marker);if(marker&&/\w/.test(marker[0]))pat="(?<!\\w)"+pat;if(marker&&/\w/.test(marker[marker.length-1]))pat+="(?!\\w)";
   const found=new RegExp(pat).exec(code);rr.forbidden.push({marker,present:!!found});if(found)fail.push({path:row.key,row:rowIndex,kind:"forbidden",marker,start:found.index});
  }
  results.push(rr);
 }
 return {results,fail,counts:{rows:results.length,functions:functionCount,order_markers:orderCount,required_raw:rawCount,forbidden:forbiddenCount,top_level:topCount,literal_calls:literalCount},status:"bounded pure-JS transcription of unchanged original source-mask/order logic; not original checker execution"};
}
return {projection};

