function matching(source,start,open,close){
  if(start>=source.length||source[start]!==open)return null;
  let d=0;for(let i=start;i<source.length;i++){if(source[i]===open)d++;else if(source[i]===close){d--;if(d===0)return i;}}return null;
}
function itemEnd(source,start){
  const field=/^(?:pub(?:\([^)]*\))?\s+)?\w+\s*:(?!:)/.exec(source.slice(start));
  if(field){
    let p=0,b=0,c=0,a=0;
    for(let i=start;i<source.length;i++){const x=source[i];if(x==="(")p++;else if(x===")"&&p)p--;else if(x==="[")b++;else if(x==="]")b--;else if(x==="{")c++;else if(x==="}"&&c)c--;else if(x==="}"&&!(p||b||a))return i-1;else if(x==="<"&&!(p||b||c))a++;else if(x===">"&&a)a--;else if(x===","&&!(p||b||c||a))return i;}return null;
  }
  let p=0,b=0;for(let i=start;i<source.length;i++){const x=source[i];if(x==="(")p++;else if(x===")"&&p)p--;else if(x==="[")b++;else if(x==="]"&&b)b--;else if(p===0&&b===0&&x===";")return i;else if(p===0&&b===0&&x==="{")return matching(source,i,"{","}");}return null;
}
function looksLikeChar(source,index){if(index+2>=source.length)return false;if(source[index+1]==="\\")return index+3<source.length&&source[index+3]==="'";return source[index+2]==="'";}
function stripNonCode(source){
  const out=source.split("");let index=0,state="code",depth=0,hashes=0;
  while(index<source.length){
    const ch=source[index],next=source[index+1]??"";
    if(state==="code"){
      if(ch==="/"&&next==="/"){out[index]=out[index+1]=" ";index+=2;state="line_comment";continue;}
      if(ch==="/"&&next==="*"){out[index]=out[index+1]=" ";index+=2;depth=1;state="block_comment";continue;}
      if(ch==='"'){out[index]=" ";index++;state="string";continue;}
      if(ch==="'"&&looksLikeChar(source,index)){out[index]=" ";index++;state="char";continue;}
      if(ch==="r"){const m=/^r(#{0,255})"/.exec(source.slice(index));if(m){hashes=m[1].length;for(let i=index;i<index+m[0].length;i++)out[i]=" ";index+=m[0].length;state="raw_string";continue;}}
      index++;continue;
    }
    if(state==="line_comment"){if(ch==="\n")state="code";else out[index]=" ";index++;continue;}
    if(state==="block_comment"){
      if(ch==="/"&&next==="*"){out[index]=out[index+1]=" ";depth++;index+=2;}
      else if(ch==="*"&&next==="/"){out[index]=out[index+1]=" ";depth--;index+=2;if(depth===0)state="code";}
      else{if(ch!=="\n")out[index]=" ";index++;}continue;
    }
    if(state==="string"||state==="char"){
      const delimiter=state==="string"?'"':"'";
      if(ch==="\\"){out[index]=" ";if(index+1<source.length){if(source[index+1]!=="\n")out[index+1]=" ";index+=2;}else index++;}
      else if(ch===delimiter){out[index]=" ";index++;state="code";}
      else{if(ch!=="\n")out[index]=" ";index++;}continue;
    }
    if(state==="raw_string"){
      const term='"'+"#".repeat(hashes);
      if(source.startsWith(term,index)){for(let i=0;i<term.length;i++)out[index+i]=" ";index+=term.length;state="code";}
      else{if(ch!=="\n")out[index]=" ";index++;}continue;
    }
    throw Error("scanner state");
  }
  return out.join("");
}
function cfgWithoutTest(expr){
  expr=expr.trim();if(expr==="test")return false;const m=/^(all|any|not)\s*\((.*)\)\s*$/s.exec(expr);if(!m)return null;
  const args=[];let depth=0,start=0;for(let i=0;i<m[2].length;i++){const c=m[2][i];if(c==="(")depth++;else if(c===")")depth--;else if(c===","&&depth===0){args.push(m[2].slice(start,i));start=i+1;}}
  if(m[2].slice(start).trim())args.push(m[2].slice(start));const vals=args.map(cfgWithoutTest);
  if(m[1]==="not")return vals.length===1&&vals[0]!==null?!vals[0]:null;
  if(m[1]==="all")return vals.includes(false)?false:vals.every(x=>x===true)?true:null;
  return vals.includes(true)?true:vals.every(x=>x===false)?false:null;
}
function stripCfgTest(code){
  const out=code.split("");let index=0;
  while(index<code.length){
    const start=code.indexOf("#[",index);if(start<0)break;
    const end=matching(code,start+1,"[","]");if(end===null)break;
    const m=/^#\[\s*cfg\s*\((.*)\)\s*\]$/s.exec(code.slice(start,end+1));
    if(!m||cfgWithoutTest(m[1])!==false){index=end+1;continue;}
    let cursor=end+1;while(true){while(cursor<code.length&&/\s/.test(code[cursor]))cursor++;if(!code.startsWith("#[",cursor))break;const e=matching(code,cursor+1,"[","]");if(e===null)throw Error("attribute");cursor=e+1;}
    const ie=itemEnd(code,cursor);if(ie===null)throw Error("test item");for(let i=start;i<=ie;i++)if(out[i]!=="\n")out[i]=" ";index=ie+1;
  }
  return out.join("");
}
function functionBody(source,marker){
  const code=stripCfgTest(stripNonCode(source));if(code.split(marker).length!==2)throw Error("function not unique");
  const start=code.indexOf(marker),end=itemEnd(code,start);if(end===null||code[end]!=="}")throw Error("no function body");
  let body=code.slice(start,end+1),cursor=marker.length,nestedCount=0;
  while(true){const m=/\bfn\s+(?:r#)?\w+/.exec(body.slice(cursor));if(!m)break;const ns=cursor+m.index,ne=itemEnd(body,ns);if(ne===null)throw Error("nested fn");body=body.slice(0,ns)+body.slice(ns,ne+1).replace(/[^\n]/g," ")+body.slice(ne+1);cursor=ne+1;nestedCount++;}
  return {body,start,end,nestedCount,code};
}
function ordered(body,markers){
  if(markers.length<2||markers.some(x=>typeof x!=="string"||!x))throw Error("invalid required order");
  let offset=0;const matches=[];
  for(const marker of markers){const at=body.indexOf(marker,offset);if(at<offset)return {ok:false,missing:marker,offset,matches};matches.push({marker,start:at,end:at+marker.length});offset=at+marker.length;}
  return {ok:true,matches};
}
return {stripNonCode,stripCfgTest,functionBody,ordered};

