function parseRow(text){
 let i=0;
 function skip(){while(i<text.length){if(/\s/.test(text[i])){i++;continue;}if(text[i]==="#"){while(i<text.length&&text[i]!=="\n")i++;continue;}break;}}
 function value(){
  skip();const c=text[i];
  if(c==='"'){const start=i++;let escaped=false;while(i<text.length){const a=text[i++];if(escaped){escaped=false;continue;}if(a==="\\"){escaped=true;continue;}if(a==='"')return JSON.parse(text.slice(start,i));}throw Error("unterminated string");}
  if(c==="'"){const start=++i;while(i<text.length&&text[i]!=="'")i++;if(i>=text.length)throw Error("literal");return text.slice(start,i++);}
  if(c==="["){i++;const a=[];skip();while(text[i]!=="]"){a.push(value());skip();if(text[i]===","){i++;skip();if(text[i]==="]")break;}else if(text[i]!=="]")throw Error("array separator "+i);}i++;return a;}
  if(c==="{"){i++;const obj={};skip();while(text[i]!=="}"){const m=/^[A-Za-z_][A-Za-z_0-9-]*/.exec(text.slice(i));if(!m)throw Error("inline key "+i);const key=m[0];i+=key.length;skip();if(text[i++]!=="=")throw Error("inline =");obj[key]=value();skip();if(text[i]===","){i++;skip();if(text[i]==="}")break;}else if(text[i]!=="}")throw Error("inline separator "+i);}i++;return obj;}
  const m=/^(true|false|[+-]?[0-9]+)(?=\s|,|\]|\}|$)/.exec(text.slice(i));if(!m)throw Error("value "+i+" "+text.slice(i,i+70));i+=m[0].length;return m[0]==="true"?true:m[0]==="false"?false:Number(m[0]);
 }
 const row={};skip();while(i<text.length){const m=/^[A-Za-z_][A-Za-z_0-9-]*/.exec(text.slice(i));if(!m)throw Error("key "+i+" "+text.slice(i,i+70));const k=m[0];i+=k.length;skip();if(text[i++]!=="=")throw Error("root =");if(k in row)throw Error("duplicate "+k);row[k]=value();skip();}return row;
}

function tables(text){
 const re=/^\[(\[?)([A-Za-z_][A-Za-z_0-9.-]*)\]\]?[ \t]*(?:\r?\n|$)/gm;
 const matches=[...text.matchAll(re)],out=[];
 for(let i=0;i<matches.length;i++){
  const m=matches[i];if(m[1]!=="["||!["boundary","protected_file"].includes(m[2]))continue;
  const end=matches[i+1]?.index??text.length,raw=text.slice(m.index,end),data=parseRow(raw.slice(m[0].length));
  out.push({kind:m[2],key:m[2]==="boundary"?data.id:data.path,raw,data});
 }
